// ---- Theme & Dpi Utilities ----
static bool ReadSystemDarkMode()
{
    HKEY hKey = nullptr;
    if (RegOpenKeyExW(HKEY_CURRENT_USER,
                      L"Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize", 0,
                      KEY_READ, &hKey) != ERROR_SUCCESS)
        return false;
    DWORD value = 1, size = sizeof(value), type = 0;
    RegQueryValueExW(hKey, L"AppsUseLightTheme", nullptr, &type, reinterpret_cast<LPBYTE>(&value),
                     &size);
    RegCloseKey(hKey);
    return value == 0;
}

static void ResolveTheme()
{
    if (g_themeMode == ThemeMode::Light)
        g_darkTheme = false;
    else if (g_themeMode == ThemeMode::Dark)
        g_darkTheme = true;
    else
        g_darkTheme = ReadSystemDarkMode();
}

static int Scale(int v)
{
    return MulDiv(v, g_dpi, 96);
}

static std::wstring LoadStr(UINT id)
{
    wchar_t buf[512] = {};
    int len = LoadStringW(g_hInst, id, buf, _countof(buf));
    return std::wstring(buf, len > 0 ? len : 0);
}

static void SetStatus(const std::wstring &s)
{
    g_status = s;
    if (g_hWnd)
        InvalidateRect(g_hWnd, nullptr, FALSE);
}

static void CreateAppFonts()
{
    LOGFONTW lf = {};
    lf.lfHeight = -Scale(16);
    lf.lfWeight = FW_NORMAL;
    lf.lfCharSet = DEFAULT_CHARSET;
    lf.lfQuality = CLEARTYPE_QUALITY;
    wcscpy_s(lf.lfFaceName, L"Segoe UI");
    g_hFont = CreateFontIndirectW(&lf);
    lf.lfWeight = FW_SEMIBOLD;
    g_hFontBold = CreateFontIndirectW(&lf);
}

static void ApplyConfiguredDpi()
{
    if (HMODULE u32 = GetModuleHandleW(L"user32.dll"))
    {
        using SetCtxFn = BOOL(WINAPI *)(DPI_AWARENESS_CONTEXT);
        auto p = reinterpret_cast<SetCtxFn>(GetProcAddress(u32, "SetProcessDpiAwarenessContext"));
        if (p)
        {
            DPI_AWARENESS_CONTEXT ctx = DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2;
            if (g_mainCfg.dpiMode == DpiMode::Unaware)
                ctx = DPI_AWARENESS_CONTEXT_UNAWARE;
            else if (g_mainCfg.dpiMode == DpiMode::System)
                ctx = DPI_AWARENESS_CONTEXT_SYSTEM_AWARE;
            else if (g_mainCfg.dpiMode == DpiMode::PerMonitor)
                ctx = DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE;
            p(ctx);
        }
    }
    HDC sdc = GetDC(nullptr);
    if (sdc)
    {
        g_dpi = GetDeviceCaps(sdc, LOGPIXELSX);
        ReleaseDC(nullptr, sdc);
    }
    if (g_dpi <= 0)
        g_dpi = 96;
}

// ---- Dwm Helpers ----
static void ApplyTitleBarTheme(HWND hwnd)
{
    HMODULE dwm = LoadLibraryW(L"dwmapi.dll");
    if (!dwm)
        return;
    auto p = reinterpret_cast<HRESULT(WINAPI *)(HWND, DWORD, LPCVOID, DWORD)>(
        GetProcAddress(dwm, "DwmSetWindowAttribute"));
    if (p)
    {
        BOOL dark = g_darkTheme ? TRUE : FALSE;
        if (FAILED(p(hwnd, 20, &dark, sizeof(dark))))
            p(hwnd, 19, &dark, sizeof(dark));
        const ThemeColors c = GetThemeColors(g_darkTheme);
        COLORREF caption = c.captionBg;
        COLORREF textCol = c.captionText;
        p(hwnd, 35, &caption, sizeof(caption));
        p(hwnd, 36, &textCol, sizeof(textCol));
        p(hwnd, 34, &caption, sizeof(caption));
    }
    FreeLibrary(dwm);
}

