/// Owns a child HWND created by this module and exposes common operations.
/// The parent must outlive this object; destroy/reset the control before the parent.
class ChildControl
{
public:
    ChildControl() noexcept = default;
    virtual ~ChildControl() noexcept;

    ChildControl(const ChildControl &) = delete;
    ChildControl &operator=(const ChildControl &) = delete;
    ChildControl(ChildControl &&other) noexcept;
    ChildControl &operator=(ChildControl &&other) noexcept;

    /// Creates a child control. Common-control classes are initialized on demand.
    bool Create(HWND parent, int controlId, LPCWSTR className, LPCWSTR text, DWORD style,
                DWORD extendedStyle, int x, int y, int width, int height,
                DWORD commonControlClasses = 0, HINSTANCE instance = nullptr) noexcept;

    /// Destroys the owned window, if it is still valid.
    void Reset() noexcept;

    /// Transfers HWND ownership to the caller without destroying the window.
    HWND Release() noexcept;

    HWND Get() const noexcept
    {
        return m_hwnd;
    }
    explicit operator bool() const noexcept
    {
        return m_hwnd != nullptr;
    }

    bool SetText(LPCWSTR text) const noexcept;
    bool Enable(bool enabled) const noexcept;
    bool Show(bool visible) const noexcept;

protected:
    LRESULT Send(UINT message, WPARAM wParam = 0, LPARAM lParam = 0) const noexcept;

private:
    HWND m_hwnd = nullptr;
};

} // namespace win32::controls

