// ---- Palette ----

ThemePalette DarkPalette() noexcept
{
    ThemePalette palette = {};
    palette.BgApp = RGB(22, 22, 25);
    palette.BgPanel = RGB(30, 30, 34);
    palette.BgCard = RGB(38, 38, 43);
    palette.BgBtn = RGB(48, 48, 54);
    palette.BgBtnHi = RGB(60, 60, 66);
    palette.BgRailHi = RGB(52, 52, 58);
    palette.Border = RGB(56, 56, 62);
    palette.BorderSoft = RGB(44, 44, 48);
    palette.TextHi = RGB(232, 232, 236);
    palette.TextMid = RGB(160, 160, 168);
    palette.TextLow = RGB(108, 108, 116);
    palette.Accent = RGB(96, 165, 250);
    palette.SelBg = RGB(48, 70, 100);
    palette.IconIdle = RGB(200, 200, 208);
    palette.IconActive = RGB(255, 255, 255);
    return palette;
}

ThemePalette LightPalette() noexcept
{
    ThemePalette palette = {};
    palette.BgApp = RGB(255, 255, 255);
    palette.BgPanel = RGB(248, 248, 248);
    palette.BgCard = RGB(238, 238, 238);
    palette.BgBtn = RGB(228, 228, 230);
    palette.BgBtnHi = RGB(218, 218, 222);
    palette.BgRailHi = RGB(232, 232, 236);
    palette.Border = RGB(200, 200, 204);
    palette.BorderSoft = RGB(220, 220, 224);
    palette.TextHi = RGB(28, 28, 32);
    palette.TextMid = RGB(100, 100, 108);
    palette.TextLow = RGB(150, 150, 158);
    palette.Accent = RGB(37, 99, 235);
    palette.SelBg = RGB(206, 224, 255);
    palette.IconIdle = RGB(60, 60, 68);
    palette.IconActive = RGB(20, 20, 28);
    return palette;
}

ThemePalette GetPalette(bool dark) noexcept
{
    return dark ? DarkPalette() : LightPalette();
}

ThemePalette GetPalette(ThemeMode mode) noexcept
{
    return GetPalette(ResolveDarkMode(mode));
}

// ---- System preference ----

bool IsSystemDarkMode() noexcept
{
    HKEY key = nullptr;
    if (RegOpenKeyExW(HKEY_CURRENT_USER,
                      L"Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize", 0,
                      KEY_QUERY_VALUE, &key) != ERROR_SUCCESS)
    {
        return false;
    }

    DWORD appsUseLightTheme = 1;
    DWORD size = sizeof(appsUseLightTheme);
    DWORD type = 0;
    const LSTATUS status = RegQueryValueExW(key, L"AppsUseLightTheme", nullptr, &type,
                                            reinterpret_cast<LPBYTE>(&appsUseLightTheme), &size);
    RegCloseKey(key);

    if (status != ERROR_SUCCESS || type != REG_DWORD)
    {
        return false;
    }
    return appsUseLightTheme == 0;
}

bool ResolveDarkMode(ThemeMode mode) noexcept
{
    switch (mode)
    {
    case ThemeMode::Light:
        return false;
    case ThemeMode::Dark:
        return true;
    case ThemeMode::System:
    default:
        return IsSystemDarkMode();
    }
}

// ---- Dpi ----

int ScaleMetric(int value, int dpi) noexcept
{
    if (dpi <= 0)
    {
        dpi = 96;
    }
    return MulDiv(value, dpi, 96);
}

// ---- DWM integration ----

/// Attribute 20 is DWMWA_USE_IMMERSIVE_DARK_MODE from Windows 10 2004 onwards;
/// 19 is the pre-release value still used by earlier builds.
static void SetDarkCaption(HWND hwnd, BOOL dark) noexcept
{
    if (FAILED(DwmSetWindowAttribute(hwnd, 20, &dark, sizeof(dark))))
    {
        DwmSetWindowAttribute(hwnd, 19, &dark, sizeof(dark));
    }
}

/// Caption colour attributes only exist on Windows 11; older builds return
/// E_INVALIDARG and keep the system caption colours.
static void SetCaptionColors(HWND hwnd, bool dark) noexcept
{
    const ThemePalette palette = GetPalette(dark);
    const COLORREF caption = palette.BgApp;
    const COLORREF text = palette.TextHi;
    const COLORREF border = palette.Border;

    DwmSetWindowAttribute(hwnd, 35, &caption, sizeof(caption));
    DwmSetWindowAttribute(hwnd, 36, &text, sizeof(text));
    DwmSetWindowAttribute(hwnd, 34, &border, sizeof(border));
}

void ApplyTitleBarTheme(HWND hwnd, bool dark) noexcept
{
    if (!hwnd)
    {
        return;
    }
    SetDarkCaption(hwnd, dark ? TRUE : FALSE);
    SetCaptionColors(hwnd, dark);
}

void ApplyControlTheme(HWND hwnd, bool dark) noexcept
{
    if (!hwnd)
    {
        return;
    }
    SetWindowTheme(hwnd, dark ? L"DarkMode_Explorer" : L"Explorer", nullptr);
}

import sys
import re

def iter_code_chars(line):
    """Yield (index, ch) plus quote state; raise nothing."""
    in_s = False
    in_c = False
    esc = False
    i = 0
    while i < len(line):
        ch = line[i]
        if in_s or in_c:
            yield i, ch, True
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif in_s and ch == '"':
                in_s = False
            elif in_c and ch == "'":
                in_c = False
        else:
            if ch == '"':
                in_s = True
                yield i, ch, True
            elif ch == "'":
                in_c = True
                yield i, ch, True
            else:
                yield i, ch, False
        i += 1


def find_line_comment(line):
    """Return index of a // comment that starts outside strings/chars."""
    prev = ''
    for i, ch, quoted in iter_code_chars(line):
        if quoted:
            prev = ch
            continue
        if ch == '/' and prev == '/':
            return i - 1
        prev = ch
    return -1


def strip_trailing_comments(text):
    out = []
    removed = 0
    for line in text.split('\n'):
        idx = find_line_comment(line)
        if idx < 0:
            out.append(line)
            continue
        code = line[:idx]
        if code.strip() == '':
            # standalone comment: keep
            out.append(line.rstrip())
            continue
        removed += 1
        out.append(code.rstrip())
    return '\n'.join(out), removed


def split_statements(text):
    lines = []
    for line in text.split('\n'):
        stripped = line.lstrip()
        if stripped.startswith('#'):
            lines.append(line)
            continue
        if ';' not in line:
            lines.append(line)
            continue
        indent = line[:len(line) - len(stripped)]
        pieces = []
        buf = []
        depth = 0
        in_s = False
        in_c = False
        esc = False
        for ch in line:
            if in_s or in_c:
                buf.append(ch)
                if esc:
                    esc = False
                elif ch == '\\':
                    esc = True
                elif in_s and ch == '"':
                    in_s = False
                elif in_c and ch == "'":
                    in_c = False
                continue
            if ch == '"':
                in_s = True
                buf.append(ch)
                continue
            if ch == "'":
                in_c = True
                buf.append(ch)
                continue
            if ch in '([{':
                depth += 1
                buf.append(ch)
                continue
            if ch in ')]}':
                depth -= 1
                buf.append(ch)
                continue
            if ch == ';' and depth <= 0:
                pieces.append(''.join(buf))
                buf = []
                continue
            buf.append(ch)
        pieces.append(''.join(buf))
        if len(pieces) == 1:
            lines.append(line)
            continue
        for piece in pieces:
            body = piece.strip()
            if not body:
                continue
            lines.append((indent + body).rstrip())
    return '\n'.join(lines)


TOKEN_RE = re.compile(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|[A-Za-z_]\w*|\d+(?:\.\d+)?|//[^\n]*|/\*.*?\*/|\S', re.S)


def tokens(text):
    text = text.replace('\r\n', '\n')
    raw = TOKEN_RE.findall(text)
    out = []
    for tok in raw:
        if tok.startswith('//'):
            continue
        if tok.startswith('/*'):
            continue
        out.append(tok)
    return out


def main():
    mode = sys.argv[1]
    src = open(sys.argv[2], encoding='utf-8').read()
    if mode == 'strip':
        result, removed = strip_trailing_comments(src)
        open(sys.argv[3], 'w', encoding='utf-8', newline='\n').write(result)
        print('stripped trailing comments:', removed)
    elif mode == 'split':
        result = split_statements(src)
        open(sys.argv[3], 'w', encoding='utf-8', newline='\n').write(result)
        print('split done')
    elif mode == 'norm':
        open(sys.argv[3], 'w', encoding='utf-8', newline='\n').write(' '.join(tokens(src)))
        print('tokens:', len(tokens(src)))
    elif mode == 'diff':
        a = tokens(open(sys.argv[2], encoding='utf-8').read())
        b = tokens(open(sys.argv[3], encoding='utf-8').read())
        n = min(len(a), len(b))
        first = None
        for i in range(n):
            if a[i] != b[i]:
                first = i
                break
        if first is None and len(a) != len(b):
            first = n
        if first is None:
            print('IDENTICAL token streams:', len(a))
        else:
            print('DIFF at token', first, 'of', len(a), len(b))
            lo = max(0, first - 12)
            print('ORIG:', ' '.join(a[lo:first + 12]))
            print('NEW :', ' '.join(b[lo:first + 12]))


if __name__ == '__main__':
    main()

