NP_API BOOL SetTheme(HWND hPanel, const NPTheme *theme)
{
    NotepadInstance *inst = GetInstance(hPanel);
    if (!inst)
        return FALSE;
    if (!theme)
    {
        inst->theme = DefaultDarkTheme();
    }
    else
    {
        inst->theme.BgApp = theme->bgApp;
        inst->theme.BgPanel = theme->bgPanel;
        inst->theme.BgCard = theme->bgCard;
        inst->theme.BgBtn = theme->bgBtn;
        inst->theme.BgBtnHi = theme->bgBtnHi;
        inst->theme.BgRailHi = theme->bgBtnHi;
        inst->theme.Border = theme->border;
        inst->theme.BorderSoft = theme->borderSoft;
        inst->theme.TextHi = theme->textHi;
        inst->theme.TextMid = theme->textMid;
        inst->theme.TextLow = theme->textLow;
        inst->theme.Accent = theme->accent;
        inst->theme.SelBg = theme->selBg;
        inst->theme.IconIdle = theme->iconIdle;
        inst->theme.IconActive = theme->iconActive;
        // Apply to RichEdit
        for (Document *d : inst->docs)
        {
            if (d->hEdit)
            {
                SendMessageW(d->hEdit, EM_SETBKGNDCOLOR, 0, inst->theme.BgApp);
                CHARFORMAT2W cf{};
                cf.cbSize = sizeof(cf);
                cf.dwMask = CFM_COLOR;
                cf.crTextColor = inst->theme.TextHi;
                SendMessageW(d->hEdit, EM_SETCHARFORMAT, SCF_DEFAULT | SCF_ALL, (LPARAM)&cf);
            }
        }
    }
    if (inst->hSelf)
        InvalidateRect(inst->hSelf, nullptr, TRUE);
    return TRUE;
}

