    outTheme->border = inst->theme.Border;
    outTheme->borderSoft = inst->theme.BorderSoft;
    outTheme->textHi = inst->theme.TextHi;
    outTheme->textMid = inst->theme.TextMid;
    outTheme->textLow = inst->theme.TextLow;
    outTheme->accent = inst->theme.Accent;
    outTheme->selBg = inst->theme.SelBg;
    outTheme->iconIdle = inst->theme.IconIdle;
    outTheme->iconActive = inst->theme.IconActive;
    return TRUE;
}

